function debounce(fn, wait) {
  let t = null;
  return function (...args) {
    if (t) clearTimeout(t);
    t = setTimeout(() => {
      t = null;
      fn.apply(this, args);        // trailing edge: last args, after quiet period
    }, wait);
  };
}

const debounce = (fn, wait) => {
